import{_ as e,c as r,o as a,ag as i}from"./chunks/framework.DQvKz0xt.js";const c=JSON.parse('{"title":"Unity - Rive 游戏运行时","description":"Rive 的 Unity 运行时。 Rive Unity 运行时目前处于 Unity 的 Mac 和 Windows 安装的 技术预览 (Technical Preview) 阶段。随着我们扩展平台支持，我们希望收集有关 API 和功能集的反馈。请通过我们的 社区 或 支持渠道 联系我们。","frontmatter":{"title":"Unity - Rive 游戏运行时","description":"Rive 的 Unity 运行时。 Rive Unity 运行时目前处于 Unity 的 Mac 和 Windows 安装的 技术预览 (Technical Preview) 阶段。随着我们扩展平台支持，我们希望收集有关 API 和功能集的反馈。请通过我们的 社区 或 支持渠道 联系我们。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 游戏运行时, Unity"}]]},"headers":[],"relativePath":"games/unity.md","filePath":"games/unity.md","lastUpdated":1774838907000}'),n={name:"games/unity.md"};function o(s,t,d,l,p,u){return a(),r("div",null,[...t[0]||(t[0]=[i('<p>Unity</p><h1 id="unity" tabindex="-1">Unity <a class="header-anchor" href="#unity" aria-label="Permalink to &quot;Unity&quot;">​</a></h1><p>Rive 的 Unity 运行时。</p><p>Rive Unity 运行时目前处于 Unity 的 Mac 和 Windows 安装的 <strong>技术预览 (Technical Preview)</strong> 阶段。随着我们扩展平台支持，我们希望收集有关 API 和功能集的反馈。请通过我们的 <a href="https://community.rive.app/c/support/" target="_blank" rel="noreferrer">社区</a> 或 <a href="https://rive.atlassian.net/servicedesk/customer/portals" target="_blank" rel="noreferrer">支持渠道</a> 联系我们。</p><p>有关 Unity 中 Rive 功能的更新列表，请参阅下面的 <a href="#feature-support">功能支持</a>。</p><h2 id="​-unity-版本支持" tabindex="-1"><a href="#unity-version-support">​</a> Unity 版本支持 <a class="header-anchor" href="#​-unity-版本支持" aria-label="Permalink to &quot;[​](#unity-version-support) Unity 版本支持&quot;">​</a></h2><p>该包支持从 2021 开始的 Unity LTS 版本（包括 Unity 6）。</p><h2 id="​-渲染支持" tabindex="-1"><a href="#rendering-support">​</a> 渲染支持 <a class="header-anchor" href="#​-渲染支持" aria-label="Permalink to &quot;[​](#rendering-support) 渲染支持&quot;">​</a></h2><p>rive-unity 运行时使用 <a href="https://rive.app/renderer" target="_blank" rel="noreferrer">Rive 渲染器</a> 并且与最新的 Rive C++ 运行时版本保持同步。</p><ul><li><a href="https://github.com/rive-app/rive-unity/blob/main/WEBGL.md" target="_blank" rel="noreferrer">WebGL</a></li><li>Metal on Mac</li><li>Metal on iOS</li><li>D3D11 on Windows</li><li>OpenGL on Windows</li><li>OpenGL on Android</li><li>Vulkan on Windows</li><li>Vulkan on Android</li><li>Vulkan on Ubuntu 24.04+ (x86_64)</li></ul><p>计划支持：</p><ul><li>D3D12</li></ul><h3 id="​-错误报告" tabindex="-1"><a href="#bug-reports">​</a> 错误报告 <a class="header-anchor" href="#​-错误报告" aria-label="Permalink to &quot;[​](#bug-reports) 错误报告&quot;">​</a></h3><p>如果你在集成 Rive Unity 运行时时遇到任何错误或意外崩溃，我们建议直接在 <a href="https://github.com/rive-app/rive-unity/issues" target="_blank" rel="noreferrer">rive-unity</a> 仓库中记录详细问题，并附上 <strong>Editor.log</strong> 以帮助提供有关可能发生情况的更多详细信息和上下文。 你可以在 <a href="https://docs.unity3d.com/Manual/LogFiles.html" target="_blank" rel="noreferrer">Unity 文档</a> 中找到有关在哪里找到 Editor.log 文件的更多详细信息。</p><p>请注意，最好在崩溃发生后立即获取 Editor.log 文件。</p><h2 id="​-功能支持" tabindex="-1"><a href="#feature-support">​</a> 功能支持 <a class="header-anchor" href="#​-功能支持" aria-label="Permalink to &quot;[​](#feature-support) 功能支持&quot;">​</a></h2><p>rive-unity 运行时使用最新的 Rive C++ 运行时。有关运行时支持的更多详细信息，请参阅 <a href="/docs/feature-support">功能支持</a> 页面。请参阅下表了解 Unity 运行时当前支持的内容。</p><table tabindex="0"><thead><tr><th><strong>功能</strong></th><th><strong>支持</strong></th></tr></thead><tbody><tr><td><a href="https://help.rive.app/runtimes/animation-playback" target="_blank" rel="noreferrer">动画播放</a></td><td>✅</td></tr><tr><td><a href="/docs/runtimes/layout#fit">适应与对齐 (Fit &amp; Alignment)</a></td><td>✅</td></tr><tr><td><a href="https://help.rive.app/game-runtimes/unity/listeners" target="_blank" rel="noreferrer">监听器 (Listeners)</a></td><td>✅</td></tr><tr><td><a href="/docs/runtimes/inputs">设置状态机输入 (Setting State Machine Inputs)</a></td><td>✅</td></tr><tr><td><a href="/docs/runtimes/rive-events">监听事件 (Listening to Events)</a></td><td>✅</td></tr><tr><td><a href="/docs/runtimes/text">运行时更新文本 (Updating text at runtime)</a></td><td>✅</td></tr><tr><td><a href="/docs/runtimes/loading-assets">带外资产 (Out-of-band assets)</a></td><td>✅</td></tr><tr><td><a href="https://help.rive.app/game-runtimes/unity/procedural-rendering" target="_blank" rel="noreferrer">程序化渲染 (Procedural rendering)</a></td><td>✅</td></tr><tr><td>PNG 图像</td><td>✅</td></tr><tr><td>JPEG 图像</td><td>✅</td></tr><tr><td>WEBP 图像</td><td>✅</td></tr></tbody></table><p><a href="https://help.rive.app/game-runtimes/unreal/common-use-cases" target="_blank" rel="noreferrer">常见用例</a><a href="https://help.rive.app/game-runtimes/unity/getting-started" target="_blank" rel="noreferrer">快速开始</a></p>',19)])])}const f=e(n,[["render",o]]);export{c as __pageData,f as default};
